<?php
namespace Tests\Feature;
use Tests\TestCase;
use App\Models\{User,TikTokCuenta,TikTokComentario,TikTokLive};
use App\Services\{TikTokIntegridad,TikTokConsulta};
use App\Jobs\ExportarTikTok;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Queue,Storage};
class TikTokAuditoriaTest extends TestCase {
 use RefreshDatabase;
 private TikTokCuenta $c;private TikTokLive $live;
 protected function setUp(): void {parent::setUp();Storage::fake('local');Queue::fake();$this->withoutMiddleware([\App\Http\Middleware\CorreoVerificado::class,\App\Http\Middleware\AceptaTerminos::class]);$this->actingAs(User::create(['usuario'=>'auditoria','name'=>'Auditor','email'=>'auditor@example.test','rol'=>'admin','activo'=>true,'password'=>'Prueba123456']));$this->c=TikTokCuenta::create(['usuario'=>'perfil_auditoria']);$n=TikTokConsulta::ahora();$this->live=TikTokLive::create(['cuenta_id'=>$this->c->id,'sala'=>'7999999999999999999','estado'=>'terminado','iniciado_ms'=>$n,'ultimo_ms'=>$n]);foreach(['uno','uno','dos']as$i=>$autor)$this->mensaje($autor,'Comentario '.$i);}
 private function mensaje(string $autor,string $texto): TikTokComentario {$n=TikTokConsulta::ahora();$m=TikTokComentario::create(['cuenta_id'=>$this->c->id,'live_id'=>$this->live->id,'clave'=>hash('sha256',$texto),'autor'=>$autor,'autor_clave'=>hash('sha256',$autor),'nombre'=>'Nombre '.$autor,'texto'=>$texto,'origen'=>'live_publico','ocurrido_ms'=>$n,'capturado_ms'=>$n,'datos_publicos'=>['usuario'=>$autor,'usuario_sala'=>'sala_publica']]);$m->update(['hash_registro'=>hash('sha256',TikTokIntegridad::json(TikTokIntegridad::original($m)))]);return $m;}
 public function test_auditar_mensajes_participantes_y_salas_no_genera_archivos(): void {foreach(['mensajes','participantes','salas']as$vista)$this->get(route('admin.tiktok.auditoria',[$this->c,'vista'=>$vista]))->assertOk()->assertViewHas('resumen',fn($r)=>$r['mensajes']===3&&$r['participantes']===2&&$r['salas']===1);Queue::assertNotPushed(ExportarTikTok::class);$this->assertSame([],Storage::disk('local')->allFiles());}
 public function test_perfil_muestra_sus_comentarios_y_el_corte_no_incluye_nuevos_registros(): void {$r=$this->get(route('admin.tiktok.auditoria',[$this->c,'actor'=>hash('sha256','uno')]));$r->assertOk()->assertSee('Comentario 0')->assertSee('Comentario 1')->assertDontSee('Comentario 2');$corte=$r->viewData('corte');$this->mensaje('uno','Mensaje posterior al corte');$this->get(route('admin.tiktok.auditoria',[$this->c,'actor'=>hash('sha256','uno'),'corte'=>$corte]))->assertOk()->assertDontSee('Mensaje posterior al corte')->assertViewHas('resumen',fn($d)=>$d['mensajes']===2);}
 public function test_detalle_escapa_texto_y_detecta_cambios_sin_modificar_el_registro(): void {$m=$this->mensaje('texto','<script>alert(1)</script>');$this->get(route('admin.tiktok.registro',[$this->c,$m]))->assertOk()->assertSee('&lt;script&gt;',false)->assertDontSee('<script>alert(1)</script>',false)->assertSee('Coincide con su hash');$hash=$m->hash_registro;$m->update(['texto'=>'Cambio externo']);$this->get(route('admin.tiktok.registro',[$this->c,$m]))->assertOk()->assertSee('El registro no coincide');$this->assertSame($hash,$m->fresh()->hash_registro);}
 public function test_auditoria_no_permite_cruzar_cuentas_ni_roles(): void {$m=TikTokComentario::first();$otra=TikTokCuenta::create(['usuario'=>'otra_cuenta']);$this->get(route('admin.tiktok.registro',[$otra,$m]))->assertNotFound();$this->get(route('admin.tiktok.auditoria',[$otra,'live_id'=>$this->live->id]))->assertNotFound();$u=User::create(['usuario'=>'sin_permiso','name'=>'Usuario','email'=>'usuario@example.test','rol'=>'cliente','activo'=>true,'password'=>'Prueba123456']);$this->actingAs($u)->get(route('admin.tiktok.auditoria',$this->c))->assertForbidden();$this->get(route('admin.tiktok.registro',[$this->c,$m]))->assertForbidden();}
}
